@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Name : string
  + Price : float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + DateOfBirth : date
}

class Registration {
  + RegistrationDate : date
}

class Assessment {
  + NeedsSummary : string
  + RecommendedStayType : StayType
}

class Stay {
  + Status : string
  + IntakeDate : date
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : string
  + OutstandingAmount : float
  + TotalAmount : float
  + Status : string
}

class CreditNote {
  + Amount : float
}

class PaymentEvent {
  + AmountPaid : float
  + PaymentDate : date
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" Category
Stay "1" -- "1..*" Invoice
Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" Inhabitant
Inhabitant "1" -- "0..*" Proposal
Proposal "1" -- "1" Stay
Inhabitant "1" -- "0..*" WaitingList
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

